//! The translations that are really incomplete run on the local decomp backend (nv-rs#930).
//!
//! About 5,760 `Translation incomplete` markers say only that the C++ exception frame or the `/GS`
//! cookie check is not translated. The addresses listed in `real_gaps.txt` (generated by
//! `scripts/fork/real_gaps.py`) leave out something the function does: an x87 status word, a read of
//! uninitialised stack, a register-only entry. When the backend is built and has a function at such
//! an address, [`apply`] registers it there. Without the backend, or without the switch, nothing is
//! registered and the engine behaves as before.
//!
//! The switch is `NV_BACKEND_GAPS=1` together with `NV_BACKEND_LIBRARY`, the library the backend
//! build wrote (the `exports.tsv` beside it holds its exports). It is a separate switch so the private
//! run's differential cases, which use the backend as a peer, keep comparing the translation.
//!
//! Only a gap the backend can answer in full is registered: the export returns one word, so a gap
//! whose caller reads `EDX`, `ST0`, an x87 or SSE status, or whose function takes or leaves
//! register state, stays on its translation (the list's `registers` rows, decided by the script
//! from the marker and the translation's signature). The switch refuses real threads (`NV_THREADS`
//! with `real`, or an engine already running them): a backend call holds one process-wide lock
//! while its import hook runs engine code, and that code can wait on another real thread that then
//! needs the lock. It also refuses a library whose `.tsv` names a symbol the library lacks. Both
//! log one `backend-gaps:` line and register nothing.

use super::backend_peer::{self, Backend, BackendPeer};
use crate::Engine;
use std::sync::OnceLock;

const LIST: &str = include_str!("real_gaps.txt");

/// Every address of the generated list with the file its marker is in and whether the backend's
/// one-word result covers it. Panics on a line that is not `<8 hex digits> <path> <eax|registers>`:
/// a damaged list must not shrink silently.
pub fn parse_list(text: &str) -> Vec<(u32, String, bool)> {
    text.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(|l| {
            let mut words = l.split_whitespace();
            let (Some(a), Some(file), Some(result), None) =
                (words.next(), words.next(), words.next(), words.next())
            else {
                panic!("real_gaps.txt: bad line {l:?}");
            };
            let one_word = match result {
                "eax" => true,
                "registers" => false,
                _ => panic!("real_gaps.txt: bad result in {l:?}"),
            };
            assert!(a.len() == 8, "real_gaps.txt: bad address in {l:?}");
            let addr = u32::from_str_radix(a, 16)
                .unwrap_or_else(|_| panic!("real_gaps.txt: bad address in {l:?}"));
            (addr, file.to_string(), one_word)
        })
        .collect()
}

/// The real-gap addresses, in the order the generated list gives them.
#[cfg(test)]
pub fn real_gaps() -> Vec<u32> {
    parse_list(LIST).into_iter().map(|(a, _, _)| a).collect()
}

/// The real gaps the backend may take over: those whose result is one word (`EAX`, or the `f32` the
/// export says it is) and that read no register state.
pub fn registerable() -> Vec<u32> {
    parse_list(LIST)
        .into_iter()
        .filter(|(_, _, one_word)| *one_word)
        .map(|(a, _, _)| a)
        .collect()
}

/// Registers the backend's function at each address of `gaps` it has, over what is there. Returns
/// the addresses it registered.
pub(crate) fn register_with<B: Backend + 'static>(
    e: &mut Engine,
    peer: &BackendPeer<B>,
    gaps: &[u32],
) -> Vec<u32> {
    let mut done = Vec::new();
    for &addr in gaps {
        if !peer.has_export(addr) {
            continue;
        }
        let peer = peer.clone();
        e.register_double(addr, move |e, args| {
            assert!(
                e.real.is_none(),
                "backend-gaps: {addr:08x} called with real threads on (NV_BACKEND_GAPS needs stepped threads)"
            );
            peer.run_export(e, addr, args)
                .unwrap_or_else(|| panic!("backend-gaps: no export at {addr:08x}"))
        });
        done.push(addr);
    }
    done
}

/// The library to load: `Some` only with the switch at `1` and a non-empty library path.
fn enabled_from(
    switch: Option<&std::ffi::OsStr>,
    library: Option<&std::ffi::OsStr>,
) -> Option<std::path::PathBuf> {
    if switch? != "1" {
        return None;
    }
    library.filter(|v| !v.is_empty()).map(Into::into)
}

/// Why the gaps stay on their translations, or the addresses registered. The library's exports
/// must all resolve before any is registered.
fn register_checked<B: Backend + 'static>(
    e: &mut Engine,
    peer: &BackendPeer<B>,
    gaps: &[u32],
) -> Result<Vec<u32>, String> {
    peer.verify()?;
    Ok(register_with(e, peer, gaps))
}

/// Whether the host asks for real threads in `NV_THREADS`.
fn real_threads_named(threads: Option<&std::ffi::OsStr>) -> bool {
    crate::thread_host::Scheme::from_name(threads.and_then(|t| t.to_str()))
        .is_ok_and(|scheme| scheme.real)
}

/// [`apply`] with the three variables given: how many addresses it registered.
fn apply_with(
    e: &mut Engine,
    switch: Option<&std::ffi::OsStr>,
    library: Option<&std::ffi::OsStr>,
    threads: Option<&std::ffi::OsStr>,
) -> usize {
    let Some(library) = enabled_from(switch, library) else {
        return 0;
    };
    if e.real.is_some() || real_threads_named(threads) {
        refuse_once(
            &REAL_NOTICE,
            "real threads are on; the gaps stay on their translations",
        );
        return 0;
    }
    static PEER: OnceLock<Result<BackendPeer<backend_peer::LibBackend>, String>> = OnceLock::new();
    let peer = PEER.get_or_init(|| {
        backend_peer::load(&library).ok_or_else(|| {
            format!(
                "{} or the exports.tsv beside it did not load",
                library.display()
            )
        })
    });
    match peer {
        Ok(peer) => match register_checked(e, peer, &registerable()) {
            Ok(done) => {
                refuse_once(
                    &DONE_NOTICE,
                    &format!(
                        "{} of {} real gaps registered",
                        done.len(),
                        registerable().len()
                    ),
                );
                done.len()
            }
            Err(why) => {
                refuse_once(&VERIFY_NOTICE, &why);
                0
            }
        },
        Err(why) => {
            refuse_once(&LOAD_NOTICE, why);
            0
        }
    }
}

static REAL_NOTICE: std::sync::Once = std::sync::Once::new();
static DONE_NOTICE: std::sync::Once = std::sync::Once::new();
static VERIFY_NOTICE: std::sync::Once = std::sync::Once::new();
static LOAD_NOTICE: std::sync::Once = std::sync::Once::new();

/// One `backend-gaps:` line per process for each notice.
fn refuse_once(once: &std::sync::Once, line: &str) {
    once.call_once(|| eprintln!("backend-gaps: {line}"));
}

/// Runs at the end of [`super::apply`]. Does nothing unless the switch is on and the library loads.
pub(crate) fn apply(e: &mut Engine) {
    apply_with(
        e,
        std::env::var_os("NV_BACKEND_GAPS").as_deref(),
        std::env::var_os("NV_BACKEND_LIBRARY").as_deref(),
        std::env::var_os("NV_THREADS").as_deref(),
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::typed::backend_peer::{Export, ImportHook};
    use crate::Ret;
    use std::cell::RefCell;
    use std::collections::HashMap;

    struct Fake(RefCell<Vec<String>>, Vec<String>);

    impl Backend for Fake {
        fn init(&self, _: *mut u8, _: u64, _: u32, _: &[u32]) -> bool {
            true
        }
        fn call(&self, wrapper: &str, args: &[u32]) -> u32 {
            self.0.borrow_mut().push(wrapper.into());
            args.iter().sum::<u32>() + 100
        }
        fn trap(&self, _: bool) -> Option<String> {
            None
        }
        fn set_import_hook(&self, _: ImportHook) {}
        fn has_symbol(&self, name: &str) -> bool {
            !self.1.iter().any(|missing| missing == name)
        }
    }

    fn peer(addresses: &[u32]) -> BackendPeer<Fake> {
        peer_lacking(addresses, &[])
    }

    /// A peer whose library lacks the named symbols: a `.tsv` from another build.
    fn peer_lacking(addresses: &[u32], missing: &[&str]) -> BackendPeer<Fake> {
        let exports = addresses
            .iter()
            .map(|&address| Export {
                address,
                wrapper: format!("decomp_call_{address:x}"),
                arity: 2,
                kind: backend_peer::ResultKind::Word,
            })
            .collect();
        BackendPeer::new(
            Fake(
                RefCell::new(Vec::new()),
                missing.iter().map(ToString::to_string).collect(),
            ),
            exports,
            vec![],
            HashMap::new(),
        )
    }

    #[test]
    fn the_generated_list_names_real_gaps_once_each() {
        let gaps = real_gaps();
        assert!(gaps.len() > 80, "{} addresses", gaps.len());
        let mut sorted = gaps.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted, gaps, "the list is sorted and has no repeats");
        // An exception-only marker is not in it: 00c55010 only lacks the FS:[0] frame.
        assert!(!gaps.contains(&0x00c5_5010));
    }

    #[test]
    fn a_gap_the_backend_has_runs_backend_code() {
        let gaps = registerable();
        let (with, without) = (gaps[0], gaps[1]);
        let mut e = Engine::new_untyped_for_test();
        e.register(without, |_, _| Ret {
            eax: 7,
            ..Ret::default()
        });
        e.register(with, |_, _| Ret {
            eax: 1,
            ..Ret::default()
        });
        let done = register_with(&mut e, &peer(&[with]), &gaps[..2]);
        assert_eq!(done, vec![with]);
        assert_eq!(e.call(with, &[2, 3]).eax, 105);
        assert_eq!(
            e.call(without, &[]).eax,
            7,
            "no backend function: the translation stays"
        );
    }

    #[test]
    fn an_address_that_is_not_a_gap_is_never_taken_over() {
        let mut e = Engine::new_untyped_for_test();
        e.register(0x00c5_5010, |_, _| Ret {
            eax: 9,
            ..Ret::default()
        });
        let done = register_with(&mut e, &peer(&[0x00c5_5010]), &[]);
        assert!(done.is_empty());
        assert_eq!(e.call(0x00c5_5010, &[]).eax, 9);
    }

    /// An engine with a sentinel at a listed address, and what `apply_with` leaves of it.
    fn untouched_by(switch: Option<&str>, library: Option<&str>) {
        untouched_with(switch, library, None);
    }

    fn untouched_with(switch: Option<&str>, library: Option<&str>, threads: Option<&str>) {
        let gap = registerable()[0];
        let mut e = Engine::new_untyped_for_test();
        e.register(gap, |_, _| Ret {
            eax: 0x5e,
            ..Ret::default()
        });
        let before = e.registered_addrs().len();
        let done = apply_with(
            &mut e,
            switch.map(std::ffi::OsStr::new),
            library.map(std::ffi::OsStr::new),
            threads.map(std::ffi::OsStr::new),
        );
        assert_eq!(done, 0);
        assert_eq!(e.registered_addrs().len(), before);
        assert_eq!(e.call(gap, &[]).eax, 0x5e);
    }

    #[test]
    fn without_the_switch_the_engine_is_as_it_was() {
        untouched_by(None, None);
        untouched_by(None, Some("/nonexistent/libfnv_decomp.so"));
        untouched_by(Some("0"), Some("/nonexistent/libfnv_decomp.so"));
    }

    #[test]
    fn the_switch_without_a_library_changes_nothing() {
        untouched_by(Some("1"), None);
        untouched_by(Some("1"), Some(""));
        untouched_by(Some("1"), Some("/nonexistent/libfnv_decomp.so"));
    }

    #[test]
    fn a_damaged_list_stops_instead_of_shrinking() {
        for bad in [
            "zzzzzzzz a.rs",
            "00c55010",
            "00c5501 a.rs",
            "00c55010 a.rs extra",
            "00c55010 a.rs",
            "00c55010 a.rs maybe",
            "00c55010 a.rs eax extra",
        ] {
            let r = std::panic::catch_unwind(|| parse_list(bad));
            assert!(r.is_err(), "{bad:?} was accepted");
        }
        assert_eq!(
            parse_list("# c\n\n 00c55010 a.rs eax\n"),
            vec![(0x00c5_5010, "a.rs".into(), true)]
        );
        assert_eq!(
            parse_list("00c55010 a.rs registers"),
            vec![(0x00c5_5010, "a.rs".into(), false)]
        );
    }

    #[test]
    fn gaps_with_register_results_stay_on_their_translation() {
        let all = real_gaps();
        let some = registerable();
        assert!(some.len() < all.len() && some.len() > 40);
        // x87 helpers (EDX, ST0, status words).
        for x87 in [0x00ed_6af6, 0x00ed_282b, 0x00ec_605d] {
            assert!(all.contains(&x87) && !some.contains(&x87), "{x87:08x}");
        }
        // Register-only entries and register or XMM state, outside units/crt: hkpWorld's outlined
        // fragments, the stale ECX of 00d68030, the stale XMM lane of 00e27c90.
        for outside in [
            0x00c9_0f40,
            0x00c9_12e0,
            0x00c9_27c0,
            0x00c9_2860,
            0x00c9_2950,
            0x00d6_8030,
            0x00e2_7c90,
        ] {
            assert!(
                all.contains(&outside) && !some.contains(&outside),
                "{outside:08x}"
            );
        }
        // An uninitialised read returns in EAX alone: the backend answers it.
        assert!(some.contains(&0x00c6_5a80));
        assert!(some.contains(&0x00e1_91a0));
    }

    /// The list's third column is the generator's decision, not a path.
    #[test]
    fn every_listed_row_has_a_result_column() {
        let rows = parse_list(LIST);
        assert!(rows.iter().any(|(_, _, one_word)| !one_word));
        assert!(rows.iter().any(|(_, _, one_word)| *one_word));
    }

    #[test]
    fn real_threads_refuse_the_switch() {
        // NV_THREADS names real threads: nothing is registered, whatever the switch says.
        untouched_with(Some("1"), Some("/nonexistent/lib.so"), Some("real"));
        assert!(real_threads_named(Some(std::ffi::OsStr::new("wake, REAL"))));
        assert!(!real_threads_named(Some(std::ffi::OsStr::new("nowake"))));
        assert!(!real_threads_named(None));
    }

    #[test]
    fn a_tsv_from_another_build_registers_nothing() {
        let gaps = registerable();
        let (a, b) = (gaps[0], gaps[1]);
        let mut e = Engine::new_untyped_for_test();
        e.register(a, |_, _| Ret {
            eax: 7,
            ..Ret::default()
        });
        // The .tsv lists both exports; the library lacks the second wrapper.
        let stale = peer_lacking(&[a, b], &[&format!("decomp_call_{b:x}")]);
        let why = register_checked(&mut e, &stale, &gaps[..2]).unwrap_err();
        assert!(why.contains(&format!("{b:08x}")), "{why}");
        assert_eq!(
            e.call(a, &[]).eax,
            7,
            "the first export is not taken over either"
        );
        // A library that is not a backend build at all.
        let foreign = peer_lacking(&[a], &["decomp_init"]);
        assert!(register_checked(&mut e, &foreign, &gaps[..1]).is_err());
        // A matching .tsv registers.
        let ok = peer(&[a, b]);
        assert_eq!(register_checked(&mut e, &ok, &gaps[..2]), Ok(vec![a, b]));
    }

    /// With the backend built (the private run), every real-gap address it has is registered and
    /// is the only thing taken over.
    #[test]
    fn with_the_backend_built_its_real_gaps_are_registered() {
        let Some(library) = backend_peer::gate::require_data("NV_BACKEND_LIBRARY") else {
            return;
        };
        let peer = backend_peer::load(&library).expect("the backend library did not load");
        let gaps = registerable();
        let mut e = Engine::new_untyped_for_test();
        let done = register_with(&mut e, &peer, &gaps);
        let expected: Vec<u32> = gaps
            .iter()
            .copied()
            .filter(|a| peer.has_export(*a))
            .collect();
        assert_eq!(done, expected);
        println!(
            "backend-gaps: {} of {} real gaps registered",
            done.len(),
            gaps.len()
        );
    }
}
